package teams

import (
	"fmt"
	"sync"
)

// Registry holds the live per-team runtime, guarded by mu.
type Registry struct {
	mu      sync.Mutex
	byslug  map[string]*Team
	disable map[string]string
}

// Disable marks a team unusable and records the reason.
func (r *Registry) Disable(slug, reason string) error {
	r.mu.Lock()
	t, ok := r.byslug[slug]
	if !ok {
		return fmt.Errorf("unknown team %q", slug)
	}
	t.Ready = false
	r.disable[slug] = reason
	r.mu.Unlock()
	return nil
}
